package br.com.confirmacao.audit.api;import br.com.confirmacao.audit.domain.*;import br.com.confirmacao.user.domain.User;import java.time.Instant;import java.util.UUID;public record AuditLogResponse(UUID id,UUID actorUserId,String actorName,String actorEmail,String actorRole,AuditAction action,String resourceType,UUID resourceId,String ipAddress,Instant createdAt){public static AuditLogResponse from(AuditLog l,User u){return new AuditLogResponse(l.getId(),l.getActorUserId(),u==null?"Não autenticado":u.getName(),u==null?null:u.getEmail(),u==null?null:u.getRole().name(),l.getAction(),l.getResourceType(),l.getResourceId(),l.getIpAddress(),l.getCreatedAt());}}
